CustomField.formula:
IF(
/*If Account is IMGA, stores ALM House Account value */
ISPICKVAL(IM_Hierarchy_Level__c, 'IM Group (IMGA)'), ALM_House_Account__c ,
IF(
/*If Account is Country Parent, stores ALM House Account value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Parent.ALM_House_Account__c,
IF(
/*If Account is Sales site, stores Country Parent Account's ALM House Account by traversing one level up the hierarchy*/
ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'), Parent.Parent.ALM_House_Account__c,False)))
